SELECT qryKathodenrecoatingAktKathoden.[Element Nr], qryKathodenrecoatingAktKathoden.Elektrolyseur, qryKathodenrecoatingAktKathoden.Position, qryKathodenrecoatingAktKathoden.[Kathoden Nr], IIf(IsNull([qryLetztesKathodenrecoating].[Anzahl von Rücklieferdatum]),0,[qryLetztesKathodenrecoating].[Anzahl von Rücklieferdatum]) AS AnzRecoatings, qryLetztesKathodenrecoating.[Max von Rücklieferdatum], qryKathodenrecoatingDOL.ElementePassiv, qryKathodenrecoatingDOL.ElementeAktiv, qryKathodenrecoatingDOL.ElementeGesamt, qryKathodenrecoatingDOL.PassiveDOL, qryKathodenrecoatingDOL.AktiveDOL, qryKathodenrecoatingDOL.GesamtDOL
FROM (qryKathodenrecoatingAktKathoden INNER JOIN qryKathodenrecoatingDOL ON qryKathodenrecoatingAktKathoden.[Kathoden Nr] = qryKathodenrecoatingDOL.[Kathoden Nr]) LEFT JOIN qryLetztesKathodenrecoating ON qryKathodenrecoatingDOL.[Kathoden Nr] = qryLetztesKathodenrecoating.Kathodennummer;
